Scheduling.LayeredPrefix.RecordedRun.par.source:
theorem RecordedRun.parent_is_key {m L : ℕ} {hm : 0 < m} {hw : 0 < work}
    {A : DeterministicScheduler m} {rule : LayerSizeRule jobs work}
    {Q : LayeredPrefix jobs work} {records : List (LayerRecord jobs work)}
    (h : RecordedRun (L := L) hw A rule (initial m hm) Q records)
    (j : Fin jobs) (v u : Fin work) (hp : Q.parent j v = some u) : u ∈ recordedKeys records j := by
  rcases h.parent_origins j v u hp with hnone | ⟨r, hr, ho, hk⟩
  · simp [initial] at hnone
  · apply mem_image.mpr
    exact ⟨r, List.mem_toFinset.mpr (List.mem_filter.mpr ⟨hr, decide_eq_true ho⟩), hk⟩

Scheduling.Instance.appendSchedule.source:
def appendSchedule (S : Assignment (vertices := vertices₁))
    (T : Assignment (vertices := vertices₂)) (d : ℕ) : Assignment (vertices := vertices₁ + vertices₂) :=
  Fin.addCases S (fun v => d + T v)

Scheduling.BatchedAdversary.FrontierCred.source:
def FrontierCredit (m L : ℕ) (history : List (LayerRecord jobs (m * L)))
    (P : LayeredPrefix jobs (m * L)) (S : Assignment (vertices := jobs * (m * L))) : Prop :=
  ∀ j, ∃ e, (∀ v ∈ P.frontier j, e ≤ S v) ∧ RevealCredit m L history j S e (P.width j)

Scheduling.BatchedAdversary.CertifiedRev.source:
def CertifiedReveals (m L : ℕ) (records : List (LayerRecord jobs (m * L)))
    (S : Assignment (vertices := jobs * (m * L))) (E : LayerRecord jobs (m * L) → ℕ) : Prop :=
  ∀ before r after, records = before ++ r :: after → RecordCredit m L before r S (E r)

Scheduling.Instance.fifoReady.source:
def fifoReady (done : Finset (Fin vertices)) (t : ℕ) : Finset (Fin vertices) :=
  univ.filter (fun v => I.release (I.owner v) ≤ t ∧ v ∉ done ∧
    ∀ u, I.edge u v → u ∈ done)

Scheduling.Instance.fifoRun.source:
def fifoRun (m : ℕ) : ℕ → Finset (Fin vertices)
  | 0 => ∅
  | t + 1 => fifoRun m t ∪ I.fifoSelect m (I.fifoReady (fifoRun m t) t)

Scheduling.LayeredPrefix.finishTime.source:
noncomputable def finishTime (P : LayeredPrefix jobs work) {m L : ℕ}
    (hw : 0 < work) (A : DeterministicScheduler m) (j : Fin jobs) : ℕ :=
  (P.frontier j).sup (A.schedule (P.toInstance L hw))

Scheduling.LayeredPrefix.CompletionRun.f.source:
theorem CompletionRun.finished {m L : ℕ} {hw : 0 < work} {A : DeterministicScheduler m}
    {rule : LayerSizeRule jobs work} {P Q : LayeredPrefix jobs work}
    (h : CompletionRun (L := L) hw A rule P Q) : ∀ j, Q.closed j = work := by
  induction h with
  | done P hd => exact hd
  | step P Q j key hk hmax hearliest tail ih => exact ih

Scheduling.LayeredPrefix.record.source:
noncomputable def record (P : LayeredPrefix jobs work) {m L : ℕ}
    (hw : 0 < work) (A : DeterministicScheduler m) (j : Fin jobs) (key : Fin work) : LayerRecord jobs work :=
  ⟨j, P.closed j, P.boundary j, key, A.schedule (P.toInstance L hw) (finProdFinEquiv (j, key))⟩

Scheduling.LayeredForest.revealTime.source:
def revealTime (S : Assignment (vertices := jobs * work)) (L : ℕ)
    (v : Fin (jobs * work)) : ℕ :=
  max ((job v).val * L) (if hp : 0 < F.vertexLevel v then
    S (F.key (job v) ⟨F.vertexLevel v - 1, by
      have := F.level_lt (job v) (position v); change F.vertexLevel v < F.depth (job v) at this; omega⟩) + 1
    else 0)

Scheduling.LayeredForest.NewLayersNarrow.source:
def NewLayersNarrow (S : Assignment (vertices := jobs * work)) (L a b : ℕ) : Prop :=
  ∀ v, a < F.revealTime S L v → F.revealTime S L v < b →
    (F.layerVertices (job v) (F.vertexLevel v)).card ≤ 1

Scheduling.Instance.FlowBound.source:
def FlowBound (S : Assignment (vertices := vertices)) (L : ℕ) : Prop :=
  ∀ v, S v < I.release (I.owner v) + L

/-- Ready vertices are revealed at the beginning of a slot. -/

Scheduling.Instance.optimum_le.source:
theorem optimum_le {m L : ℕ} (hm : 0 < m) {O : Assignment (vertices := vertices)}
    (hO : I.Valid m O) (hL : I.FlowBound O L) : I.optimum m hm ≤ L :=
  Nat.find_min' (I.exists_offline_bound hm) ⟨O, hO, hL⟩

Scheduling.Instance.optimum_le_maxFlow.source:
theorem optimum_le_maxFlow {m : ℕ} (hm : 0 < m) {O : Assignment (vertices := vertices)}
    (hO : I.Valid m O) : I.optimum m hm ≤ I.maxFlow O :=
  I.optimum_le hm hO ((I.flowBound_iff_maxFlow_le O _).mpr le_rfl)

Scheduling.Instance.survivorIndex.source:
noncomputable def survivorIndex {S : Assignment (vertices := vertices)} {s : ℕ}
    (v : Fin vertices) (hv : v ∈ I.survivors S s) : Fin (I.survivors S s).card :=
  ((I.survivors S s).orderIsoOfFin rfl).symm ⟨v, hv⟩

Scheduling.Instance.splice_preserves_pre.source:
theorem splice_preserves_prefix {S : Assignment (vertices := vertices)} {s : ℕ}
    (T : Assignment (vertices := (I.survivors S s).card)) {v : Fin vertices}
    (hv : S v < s) : I.splice S s T v = S v := by
  have hn : v ∉ I.survivors S s := by simpa [survivors] using hv
  simp only [splice, dif_neg hn]

Scheduling.executionPrefix.source:
noncomputable def executionPrefix {vertices : ℕ}
    (S : Assignment (vertices := vertices)) (t : ℕ) : Finset ℕ :=
  (univ.filter (fun v => S v < t)).image Fin.val

Scheduling.executionSlot.source:
noncomputable def executionSlot {vertices : ℕ}
    (S : Assignment (vertices := vertices)) (t : ℕ) : Finset ℕ :=
  (univ.filter (fun v => S v = t)).image Fin.val

Scheduling.ReadySnapshot.assignSlot.source:
def assignSlot (m : ℕ) (v : V) : Option ℕ :=
  let A := (range (Q.duration m)).filter (fun k => v ∈ Q.action m k)
  if h : A.Nonempty then some (A.min' h) else none

Scheduling.sffStep.source:
def sffStep (m : ℕ) (_t : ℕ) (observation : PublicSnapshot) (state : SFFMemory) :
    Finset ℕ × SFFMemory :=
  let plan := state.getD (observation, 0)
  (plan.1.action m plan.2,
    if plan.2 + 1 < plan.1.duration m then some (plan.1, plan.2 + 1) else none)

Scheduling.Instance.readyObservation.source:
def readyObservation (S : Assignment (vertices := vertices)) (t : ℕ) : FIFOObservation :=
  (univ.filter (fun v => I.release (I.owner v) ≤ t ∧ t ≤ S v ∧
    ∀ u, I.edge u v → S u < t)).image I.fifoPriority

Scheduling.StarChain.MiddleAt.source:
def MiddleAt (long : Fin jobs → Bool) (hm : 0 < m)
    (S : Assignment (vertices := jobs * (3 * m))) (t : ℕ) : Prop :=
  ∃ j, long j = true ∧ S (middle hm j) = t

Scheduling.StarChain.leafParent.source:
def leafParent (long : Fin jobs → Bool) (hm : 0 < m)
    (v : Fin (jobs * (3 * m))) : Fin (jobs * (3 * m)) :=
  if long (job v) then middle hm (job v) else root hm (job v)
